/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Mod, pprintUseUnicode, printLatex, symbols } from '../../src';
import { text } from '../sympy-str';

describe("doctests of sympy.printing.printer", () => {
  it("print_latex(Mod(x, m))", () => {
    const [x, m] = symbols('x m');
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(printLatex(Mod(x, m), {}))).toBe('x \\bmod m');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  // no value
  //   print_latex(ModOp(x, m))
  //   => \operatorname{Mod}{\left(x, m\right)}
  it.todo("print_latex(ModOp(x, m))");
  // no value
  //   print_latex(ModOp(x, m), mode='inline')  # ok
  //   => $\operatorname{Mod}{\left(x, m\right)}$
  it.todo("print_latex(ModOp(x, m), mode='inline')  # ok");
  // no value
  //   print_latex(ModOpModeWrong(x, m), mode='inline')  # bad
  //   => $\operatorname{Mod}{\left($x$, $m$\right)}$
  it.todo("print_latex(ModOpModeWrong(x, m), mode='inline')  # bad");
  // no value
  //   print_latex(ModOp(ModOp(x, m), Integer(7)))  # ok
  //   => \operatorname{Mod}{\left(\operatorname{Mod}{\left(x, m\right)}, 7\right)}
  it.todo("print_latex(ModOp(ModOp(x, m), Integer(7)))  # ok");
  // no value
  //   print_latex(ModOpNestedWrong(ModOpNestedWrong(x, m), Integer(7)))  # bad
  //   => \operatorname{Mod}{\left(ModOpNestedWrong(x, m), 7\right)}
  it.todo("print_latex(ModOpNestedWrong(ModOpNestedWrong(x, m), Integer(7)))  # bad");
  // no value
  //   print_latex(ModOp(Float(1) * x, m), full_prec=True)  # ok
  //   => \operatorname{Mod}{\left(1.00000000000000 x, m\right)}
  it.todo("print_latex(ModOp(Float(1) * x, m), full_prec=True)  # ok");
  // no value
  //   print_latex(ModOpSettingsWrong(Float(1) * x, m), full_prec=True)  # bad
  //   => \operatorname{Mod}{\left(1.0 x, m\right)}
  it.todo("print_latex(ModOpSettingsWrong(Float(1) * x, m), full_prec=True)  # bad");
});
